import { Record, RecordId, ResolvableShape, Shape } from './plugins'
import { js2xml, type Element } from 'xml-js'

export function unloadBuilder({ scope, scopeId, table }: { scope: string; scopeId: string; table?: string }) {
    const recordUpdateElements = []
    const xmlJsObj = {
        declaration: {
            attributes: {
                version: '1.0',
            },
        },
        elements: [
            {
                type: 'element',
                name: 'record_update',
                attributes: {
                    table,
                },
                elements: recordUpdateElements,
            },
        ],
    }
    const end = () => js2xml(xmlJsObj, { spaces: 2, cdataFn: (cData) => cData.replaceAll(']]>', ']]]]><![CDATA[>') })

    // Root Builder
    return {
        recordUpdateElements,
        end,
        record: (record: Record, updateName: string) => {
            const table = record.getTable()

            // TODO: Let the plugins define this kind of thing?
            const extraAttributes =
                table === 'sys_dictionary'
                    ? {
                          element: record.get('element').ifString()?.getValue() ?? '',
                          table: record.get('name').ifString()?.getValue() ?? '',
                      }
                    : {}

            const rec = recordXml(recordUpdateElements, table, record.getId().getValue(), {
                attr: { action: record.getAction(), ...extraAttributes },
            })
            rec.field('sys_scope', scopeId, { display_value: scope })
            rec.field('sys_update_name', updateName)
            return rec
        },
    }
}

// Reading material for how the platform serializes various records:
// https://code.devsnc.com/dev/glide/blob/be807416d00ae58418085172572318b7bebdb83e/glide/src/com/glide/update/AbstractUpdateSaver.java#L421
// https://code.devsnc.com/dev/glide/tree/1b10419eb9c803cff2cb108e9bde9ecc59f59b67/glide/src/com/glide/update/saver
export function recordXml(
    recordElements: Element[],
    tableName: string,
    id: string | number,
    options: {
        attr?: globalThis.Record<string, string>
        excludeScopeElement?: boolean
    } = {}
) {
    const recordElement: Element = {
        type: 'element',
        name: tableName,
        attributes: options.attr || { action: 'INSERT_OR_UPDATE' },
        elements: [
            {
                type: 'element',
                name: 'sys_id',
                elements: [
                    {
                        type: 'text',
                        text: `${id}`,
                    },
                ],
            },
        ],
    }
    recordElements.push(recordElement)
    // Record Builder
    return {
        field(columnName: string, value: unknown, attributes: globalThis.Record<string, string> = {}) {
            if (value instanceof ResolvableShape) {
                value = value.resolve()
            }

            if (value instanceof Record) {
                value = value.getId()
            }

            if (value instanceof RecordId) {
                attributes = { ...attributes, ...serializeKeys(value) }
            }

            const { stringValue, contentType } =
                value instanceof Shape
                    ? value.toString().pipe((s) => ({ stringValue: s.getValue(), contentType: s.getContentType() }))
                    : { stringValue: `${value ?? ''}`, contentType: 'plain' }

            /*
                &nbsp is not a predefined entity for XML, to overcome that the platform uses &amp;nbsp; in XMLs.
                When we transform XML that contains &amp;nbsp; that translates to `&nbsp;`.
                But when fluent generates the XML from source it creates XML with &nbsp; which makes the XML invalid since `nbsp` is not defined.

                So we are replacing &nbsp; with &amp;nbsp; to ensure the XML is valid.
            */
            const sanitizedValue = stringValue.replaceAll('&nbsp;', '&amp;nbsp;')

            const columnNameElement: Element = {
                type: 'element',
                name: columnName,
                attributes,
                elements: [],
            }
            recordElement.elements?.push(columnNameElement)

            if (sanitizedValue) {
                contentType === 'plain'
                    ? columnNameElement.elements?.push({ type: 'text', text: sanitizedValue })
                    : columnNameElement.elements?.push({ type: 'cdata', cdata: sanitizedValue })
            }

            return columnNameElement
        },
        addSysScope(scope: string, scopeId: string) {
            const sysScopeElement: Element = {
                type: 'element',
                name: 'sys_scope',
                attributes: { display_value: scope },
                elements: [
                    {
                        type: 'text',
                        text: scopeId,
                    },
                ],
            }
            recordElement.elements?.push(sysScopeElement)
            return sysScopeElement
        },
    }
}

function serializeKeys(id: RecordId): globalThis.Record<string, string> | undefined {
    const keys = id.getKeys()
    return keys
        ? Object.fromEntries(Object.entries(keys).map(([k, v]) => [k, v instanceof RecordId ? v.getValue() : v]))
        : undefined
}
